// [Manus] Infinite Credits Visual Injection
(function() {
    function injectCredits() {
        document.querySelectorAll('div, span, p').forEach(el => {
            if (el.textContent.includes('credits') || el.textContent.includes('créditos')) {
                if (el.children.length === 0) {
                    el.innerHTML = '<span style="color:#00ff00; font-weight:bold; text-shadow: 0 0 5px #00ff00;">999+ Créditos (Mr Sem Limite)</span>';
                }
            }
        });
    }
    setInterval(injectCredits, 2000);
})();


(function() {
    console.log("[Manus] Mr Sem Limite Ext 2 - Clean Bridge Active");
    
    function findChatInput() {
        return document.querySelector('textarea[placeholder*="lovable" i]') || 
               document.querySelector('textarea') ||
               document.querySelector('[contenteditable="true"]');
    }

    function findSendButton() {
        return document.querySelector('button[type="submit"]') || 
               document.querySelector('button:has(svg)');
    }

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
            const input = findChatInput();
            if (document.activeElement === input) {
                const msg = input.value || input.textContent;
                if (msg.trim()) {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    console.log("[Manus] Intercepted Enter, sending:", msg);
                    chrome.runtime.sendMessage({
                        action: 'sendMessage',
                        mensagem: msg
                    }, (res) => {
                        if (res && res.ok) {
                            if (input.tagName === 'TEXTAREA') input.value = '';
                            else input.textContent = '';
                        }
                    });
                }
            }
        }
    }, true);

    document.addEventListener('click', (e) => {
        const btn = findSendButton();
        if (btn && (e.target === btn || btn.contains(e.target))) {
            const input = findChatInput();
            const msg = input.value || input.textContent;
            if (msg.trim()) {
                e.preventDefault();
                e.stopImmediatePropagation();
                console.log("[Manus] Intercepted Click, sending:", msg);
                chrome.runtime.sendMessage({
                    action: 'sendMessage',
                    mensagem: msg
                }, (res) => {
                    if (res && res.ok) {
                        if (input.tagName === 'TEXTAREA') input.value = '';
                        else input.textContent = '';
                    }
                });
            }
        }
    }, true);
})();


